-- Freeze recipient security versions as well as authorizing facility access.
CREATE OR REPLACE FUNCTION refurbishment_context(ref uuid, actor uuid, facility uuid DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE AS $$
 SELECT jsonb_build_object('configuration',refurbishment_configuration(ref),'owner_access',(SELECT jsonb_build_object('id',recipient.id,'status',recipient.status,'session_version',recipient.session_version,'membership_id',rm.id,'membership_version',rm.version,'role',rm.role,'active',rm.active) FROM items owned JOIN users recipient ON recipient.id=owned.owner_user_id JOIN memberships rm ON rm.user_id=recipient.id WHERE owned.subject_id=ref),'staff',(SELECT jsonb_build_object('actor_id',u.id,'session_version',u.session_version,'status',u.status,'membership',to_jsonb(m),'facility_party_id',p.id,'facility_version',l.version,'facility_active',l.active,'facility_review',l.review_status,'operator_version',o.version,'operator_review',o.review_status) FROM users u JOIN memberships m ON m.user_id=u.id JOIN parties p ON p.id=COALESCE(facility,(SELECT party_id FROM custody_current WHERE subject_id=ref)) JOIN places l ON l.id=p.place_id JOIN organizations o ON o.id=l.organization_id WHERE u.id=actor),
 'assurance',COALESCE((SELECT jsonb_agg(jsonb_build_object('subject_id',i.subject_id,'assurance',to_jsonb(sc),'authorization',to_jsonb(ma),'assessment',to_jsonb(ac)) ORDER BY i.subject_id) FROM items i LEFT JOIN sanitization_current sc ON sc.subject_id=i.subject_id LEFT JOIN media_authorization_current ma ON ma.subject_id=i.subject_id LEFT JOIN assessment_current ac ON ac.subject_id=i.subject_id WHERE i.subject_id=ref OR i.subject_id IN(SELECT medium_id FROM media_inventory_entries WHERE parent_id=ref)),'[]'),
 'work_id',(SELECT id FROM refurbishment_records WHERE subject_id=ref AND kind='work' ORDER BY version DESC LIMIT 1),'test_id',(SELECT id FROM refurbishment_records WHERE subject_id=ref AND kind='test' ORDER BY version DESC LIMIT 1),'na_id',(SELECT id FROM refurbishment_records WHERE subject_id=ref AND kind='fan_na' ORDER BY version DESC LIMIT 1))
$$;
